  1	// Admission: can this (model, artifact, runner, parameters) run here, now?
  2	//
  3	// The result keeps two refusals apart: `incompatible` (this hardware can
  4	// never run these parameters) and `insufficient-now` (another process holds
  5	// the memory at the moment). Numbers are estimates, labelled as such, from
  6	// the model's measured memory profile when the catalog has one (gpt-oss-20b
  7	// was calibrated on the RTX 3060 in Phase 0) and from the file size otherwise.
  8	
  9	const MIB = 1024 * 1024;
 10	const GIB = 1024 * MIB;
 11	const CUDA_CONTEXT_BYTES = 200 * MIB;
 12	const RUNNER_RAM_BYTES = 768 * MIB;
 13	const GPU_MARGIN_BYTES = 256 * MIB;
 14	const RAM_MARGIN_BYTES = 1 * GIB;
 15	const KV_FACTOR = Object.freeze({ f16: 1, q8_0: 0.53125, q4_0: 0.28125 });
 16	const DEFAULT_KV_BYTES_PER_TOKEN = 64 * 1024;
 17	const DEFAULT_LAYERS = 48;
 18	const UNKNOWN_MOE_EXPERT_FRACTION = 0.9;
 19	
 20	function gib(bytes) {
 21	    return `${(bytes / GIB).toFixed(1)} GiB`;
 22	}
 23	
 24	function result(status, reason, estimate, warnings = []) {
 25	    return Object.freeze({ status, reason, estimate: Object.freeze({ ...estimate, isEstimate: true }), warnings: Object.freeze(warnings) });
 26	}
 27	
 28	// Custom runner policies build their answers with the same shape.
 29	export { result as admissionResult };
 30	
 31	// Weights split between GPU and CPU for llama.cpp. For a mixture-of-experts
 32	// model, --n-cpu-moe keeps the expert tensors of that many layers in RAM
 33	// while attention and shared weights stay on the GPU.
 34	function llamaWeightSplit(model, size, params) {
 35	    const memory = model.memory || {};
 36	    const layers = memory.layers || DEFAULT_LAYERS;
 37	    const layerFraction = Math.min(1, params.nGpuLayers / layers);
 38	    const profiled = Number.isFinite(memory.nonExpertBytes) && Number.isFinite(memory.expertBytesPerLayer);
 39	    let nonExpert;
 40	    let expertPerLayer;
 41	    if (profiled) {
 42	        nonExpert = memory.nonExpertBytes;
 43	        expertPerLayer = memory.expertBytesPerLayer;
 44	    } else if (model.architecture === 'moe') {
 45	        expertPerLayer = (size * UNKNOWN_MOE_EXPERT_FRACTION) / layers;
 46	        nonExpert = size - expertPerLayer * layers;
 47	    } else {
 48	        nonExpert = size;
 49	        expertPerLayer = 0;
 50	    }
 51	    const gpuLayers = Math.round(layerFraction * layers);
 52	    const expertLayersOnGpu = Math.max(0, gpuLayers - Math.min(params.nCpuMoe || 0, layers));
 53	    const gpuWeights = Math.min(size, nonExpert * layerFraction + expertPerLayer * expertLayersOnGpu);
 54	    return { gpuWeights, cpuWeights: Math.max(0, size - gpuWeights), profiled };
 55	}
 56	
 57	function computeBufferBytes(params) {
 58	    const ubatch = params.ubatchSize || 512;
 59	    if (params.flashAttn === 'off') {
 60	        // Measured: 2,146 MiB at 16k context and a 512 ubatch without flash attention.
 61	        return 2146 * MIB * (params.ctxSize / 16384) * (ubatch / 512);
 62	    }
 63	    // Measured: 175 MiB at a 256 ubatch and 215 MiB at 512 with flash attention.
 64	    return (135 + 0.16 * ubatch) * MIB;
 65	}
 66	
 67	export function estimateLlamaCpp({ model, source, params }) {
 68	    const size = source.size || 0;
 69	    const { gpuWeights, cpuWeights, profiled } = llamaWeightSplit(model, size, params);
 70	    const kvFactor = (KV_FACTOR[params.cacheTypeK] + KV_FACTOR[params.cacheTypeV]) / 2 || 1;
 71	    const kvPerToken = model.memory?.kvBytesPerToken || DEFAULT_KV_BYTES_PER_TOKEN;
 72	    const kvBytes = kvPerToken * params.ctxSize * kvFactor + (model.memory?.fixedKvBytes || 0);
 73	    const computeBytes = computeBufferBytes(params);
 74	    const gpuBytes = params.nGpuLayers > 0 ? gpuWeights + kvBytes + computeBytes + CUDA_CONTEXT_BYTES : 0;
 75	    return {
 76	        weightsBytes: size,
 77	        gpuWeightsBytes: Math.round(gpuWeights),
 78	        cpuWeightsBytes: Math.round(cpuWeights),
 79	        kvBytes: Math.round(kvBytes),
 80	        computeBytes: Math.round(computeBytes),
 81	        gpuBytes: Math.round(gpuBytes),
 82	        ramBytes: Math.round(cpuWeights + RUNNER_RAM_BYTES),
 83	        basis: profiled ? 'measured memory profile' : 'file size heuristic (no memory profile for this model)',
 84	    };
 85	}
 86	
 87	export function estimateOllama({ model, source, params }) {
 88	    const size = source.size || 0;
 89	    const layers = model.memory?.layers || DEFAULT_LAYERS;
 90	    const kvBytes = (model.memory?.kvBytesPerToken || DEFAULT_KV_BYTES_PER_TOKEN) * params.numCtx
 91	        * (KV_FACTOR[params.kvCacheType] || 1) + (model.memory?.fixedKvBytes || 0);
 92	    // Ollama places whole layers itself unless numGpu pins the count.
 93	    const gpuWeights = params.numGpu === null || params.numGpu === undefined
 94	        ? null
 95	        : size * Math.min(1, params.numGpu / layers);
 96	    return {
 97	        weightsBytes: size,
 98	        gpuWeightsBytes: gpuWeights === null ? null : Math.round(gpuWeights),
 99	        kvBytes: Math.round(kvBytes),
100	        gpuBytes: gpuWeights === null ? null : Math.round(gpuWeights + kvBytes + CUDA_CONTEXT_BYTES),
101	        totalBytes: Math.round(size + kvBytes + CUDA_CONTEXT_BYTES),
102	        basis: size ? 'download size' : 'unknown size until the tag is pulled',
103	    };
104	}
105	
106	function ramWarning(ramBytes, memory) {
107	    if (!memory?.availableBytes || !ramBytes) return [];
108	    if (ramBytes <= memory.availableBytes * 0.5) return [];
109	    return [`Uses about ${gib(ramBytes)} of system RAM; ${gib(memory.availableBytes)} is available now. `
110	        + 'Close other applications or reduce the context if the desktop becomes slow.'];
111	}
112	
113	function diskShortage(remainingBytes, disk) {
114	    return Number.isFinite(disk?.freeBytes) && remainingBytes * 1.05 > disk.freeBytes;
115	}
116	
117	function otherGpuUsers(gpu) {
118	    const users = (gpu.processes || []).map((process) => `${process.name} (${gib(process.usedBytes)})`);
119	    return users.length ? `; other GPU users: ${users.join(', ')}` : '';
120	}
121	
122	// The llama-server policy: weights split between GPU and RAM by nCpuMoe,
123	// KV cache and compute buffers on the GPU. Used by llama.cpp and every
124	// runner that serves the same GGUF files with the same memory layout.
125	// `extra` adds a runner's own RAM beside llama-server (LM Studio's daemon).
126	export function admitLlamaServer({ model, source, params, gpu, memory, disk, remainingDownloadBytes = 0 }, extra = null) {
127	    const base = estimateLlamaCpp({ model, source, params });
128	    const estimate = extra
129	        ? { ...base, ramBytes: base.ramBytes + extra.ramBytes, basis: `${base.basis}, plus ${extra.basis}` }
130	        : base;
131	    const warnings = ramWarning(estimate.ramBytes, memory);
132	    if (estimate.gpuBytes > gpu.totalBytes * 0.97) {
133	        return result('incompatible', `Needs about ${gib(estimate.gpuBytes)} of GPU memory; the GPU has `
134	            + `${gib(gpu.totalBytes)}. Keep more expert layers in RAM (nCpuMoe) or reduce ctxSize.`, estimate, warnings);
135	    }
136	    if (memory.totalBytes && estimate.ramBytes > memory.totalBytes) {
137	        return result('incompatible', `Needs about ${gib(estimate.ramBytes)} of RAM; this machine has `
138	            + `${gib(memory.totalBytes)}.`, estimate, warnings);
139	    }
140	    if (estimate.gpuBytes > gpu.freeBytes - GPU_MARGIN_BYTES) {
141	        return result('insufficient-now', `Needs about ${gib(estimate.gpuBytes)} of GPU memory; `
142	            + `${gib(gpu.freeBytes)} is free now${otherGpuUsers(gpu)}.`, estimate, warnings);
143	    }
144	    if (memory.availableBytes && estimate.ramBytes > memory.availableBytes - RAM_MARGIN_BYTES) {
145	        return result('insufficient-now', `Needs about ${gib(estimate.ramBytes)} of RAM; `
146	            + `${gib(memory.availableBytes)} is available now.`, estimate, warnings);
147	    }
148	    if (diskShortage(remainingDownloadBytes, disk)) {
149	        return result('insufficient-now', `The download needs ${gib(remainingDownloadBytes * 1.05)} of free disk; `
150	            + `${gib(disk.freeBytes)} is free.`, estimate, warnings);
151	    }
152	    return result('ok', null, estimate, warnings);
153	}
154	
155	// LM Studio runs the same llama-server (its bundled b11026) with the flags the
156	// adapter sets through its SDK and checks in the engine's command line, so
157	// the llama-server model applies, plus LM Studio's daemon and workers: about
158	// 0.6 GB at idle (llmster about 507 MB, a node worker about 103 MB; runners
159	// plan §11, research), budgeted at 768 MiB.
160	const LMSTUDIO_RAM_BYTES = 768 * MIB;
161	
162	export function admitLmStudio(input) {
163	    return admitLlamaServer(input, { ramBytes: LMSTUDIO_RAM_BYTES, basis: 'LM Studio\'s daemon (768 MiB)' });
164	}
165	
166	// The Ollama policy: Ollama places whole layers itself unless numGpu pins them.
167	export function admitOllama({ model, source, params, gpu, memory, disk, remainingDownloadBytes = 0 }) {
168	    const estimate = estimateOllama({ model, source, params });
169	    const gpuShare = estimate.gpuBytes ?? Math.min(estimate.totalBytes, Math.max(0, gpu.freeBytes - GPU_MARGIN_BYTES));
170	    const ramBytes = Math.max(0, estimate.totalBytes - gpuShare) + RUNNER_RAM_BYTES;
171	    const withRam = { ...estimate, ramBytes };
172	    const warnings = ramWarning(ramBytes, memory);
173	    if (estimate.gpuBytes !== null && estimate.gpuBytes > gpu.totalBytes * 0.97) {
174	        return result('incompatible', `numGpu puts about ${gib(estimate.gpuBytes)} on a GPU with `
175	            + `${gib(gpu.totalBytes)}; lower numGpu or leave it unset.`, withRam, warnings);
176	    }
177	    if (memory.totalBytes && estimate.totalBytes > gpu.totalBytes + memory.totalBytes) {
178	        return result('incompatible', `Needs about ${gib(estimate.totalBytes)} of GPU memory and RAM together.`,
179	            withRam, warnings);
180	    }
181	    if (gpu.freeBytes < GIB) {
182	        return result('insufficient-now', `Only ${gib(gpu.freeBytes)} of GPU memory is free${otherGpuUsers(gpu)}.`,
183	            withRam, warnings);
184	    }
185	    if (memory.availableBytes && ramBytes > memory.availableBytes - RAM_MARGIN_BYTES) {
186	        return result('insufficient-now', `Needs about ${gib(ramBytes)} of RAM; `
187	            + `${gib(memory.availableBytes)} is available now.`, withRam, warnings);
188	    }
189	    if (diskShortage(remainingDownloadBytes, disk)) {
190	        return result('insufficient-now', `The download needs ${gib(remainingDownloadBytes * 1.05)} of free disk; `
191	            + `${gib(disk.freeBytes)} is free.`, withRam, warnings);
192	    }
193	    return result('ok', null, withRam, warnings);
194	}
195	
196	// vLLM on this GPU (measured with Qwen3-4B-AWQ on the RTX 3060 Laptop):
197	// CUDA reports about 94 % of nvidia-smi's total as usable, and besides the
198	// weights and the KV cache vLLM holds activations, the CUDA context and
199	// allocator slack, budgeted at 768 MiB.
200	const VLLM_USABLE_SHARE = 0.94;
201	const VLLM_OVERHEAD_BYTES = 768 * MIB;
202	const VLLM_MAX_UTILIZATION = 0.9;
203	const VLLM_RUNNER_RAM_BYTES = 3 * GIB;
204	// System RAM with CPU offload (cpuOffloadGb), measured on 2026-09-25 on the
205	// RTX 3060 Laptop machine (31 GiB RAM, its 8 GiB swap already full) with
206	// gpt-oss-20b and cpuOffloadGb 10. On 8080 available memory fell from 23.2 to
207	// 2.2 GiB, and `free` showed shared memory grow by about 18.1 GiB (1.81 x the
208	// offload: vLLM's pinned copies, more than any one process's RssShmem shows);
209	// the engine and API server held about 3.0 GiB more. In the fixture it fell
210	// by at least 20.1 GiB before a guard stopped it. The old estimate (offload +
211	// 3 GiB, 13.0 GiB) admitted that. Two runs on one machine, so the estimate is
212	// (1.81 x offload + 3.0 GiB) x 1.15, an offload run must leave max(4 GiB,
213	// 10 % of RAM) available, and the controller's memory guard is the backstop.
214	const VLLM_OFFLOAD_RAM_FACTOR = 1.81;
215	const VLLM_OFFLOAD_RESIDENT_BYTES = 3 * GIB;
216	const VLLM_OFFLOAD_RAM_MARGIN = 1.15;
217	const VLLM_RAM_FLOOR_BYTES = 4 * GIB;
218	const VLLM_RAM_FLOOR_SHARE = 0.1;
219	
220	// The vLLM policy: all weights on the GPU unless the admin explicitly offloads
221	// some to RAM (cpuOffloadGb, much slower), a KV cache sized for maxModelLen,
222	// and a GPU memory share (--gpu-memory-utilization) taken from what is free.
223	export function admitVllm({ model, source, params, gpu, memory, disk, remainingDownloadBytes = 0 }) {
224	    const size = source.size || 0;
225	    const offloadBytes = Math.round((params.cpuOffloadGb || 0) * GIB);
226	    const gpuWeightsBytes = Math.max(0, size - offloadBytes);
227	    const kvFactor = params.kvCacheDtype === 'fp8' ? 0.5 : 1;
228	    const kvBytes = Math.round((model.memory?.kvBytesPerToken || DEFAULT_KV_BYTES_PER_TOKEN) * params.maxModelLen * kvFactor);
229	    const gpuBytes = gpuWeightsBytes + kvBytes + VLLM_OVERHEAD_BYTES;
230	    const usable = (share) => share * gpu.totalBytes * VLLM_USABLE_SHARE;
231	    const fromFree = Math.floor(Math.min(VLLM_MAX_UTILIZATION, (gpu.freeBytes - 2 * GPU_MARGIN_BYTES) / gpu.totalBytes) * 100) / 100;
232	    const gpuMemoryUtilization = params.gpuMemoryUtilization ?? fromFree;
233	    const ramBytes = offloadBytes > 0
234	        ? Math.round((offloadBytes * VLLM_OFFLOAD_RAM_FACTOR + VLLM_OFFLOAD_RESIDENT_BYTES) * VLLM_OFFLOAD_RAM_MARGIN)
235	        : VLLM_RUNNER_RAM_BYTES;
236	    const ramFloor = Math.max(VLLM_RAM_FLOOR_BYTES, (memory.totalBytes || 0) * VLLM_RAM_FLOOR_SHARE);
237	    const estimate = {
238	        weightsBytes: size, gpuWeightsBytes, cpuWeightsBytes: offloadBytes, kvBytes, gpuBytes, ramBytes,
239	        gpuMemoryUtilization, basis: offloadBytes > 0
240	            ? 'snapshot size, KV cache for maxModelLen, a measured vLLM overhead, and RAM for the offload measured with gpt-oss-20b plus 15 %'
241	            : 'snapshot size, KV cache for maxModelLen and a measured vLLM overhead',
242	        // With offload the controller keeps this much RAM available while the runner runs (memory guard).
243	        ...(offloadBytes > 0 ? { ramFloorBytes: Math.round(ramFloor) } : {}),
244	    };
245	    const warnings = ramWarning(ramBytes, memory);
246	    if (offloadBytes > 0) {
247	        warnings.push(`Offloading ${gib(offloadBytes)} of weights to system RAM makes generation much slower: `
248	            + 'every token reads them over PCIe.');
249	    }
250	    if (offloadBytes > size) {
251	        return result('incompatible', `cpuOffloadGb (${gib(offloadBytes)}) is larger than the model (${gib(size)}).`, estimate, warnings);
252	    }
253	    // Whether it can ever fit: at the admin's share when set, else at vLLM's usual maximum.
254	    const ceiling = params.gpuMemoryUtilization ?? VLLM_MAX_UTILIZATION;
255	    if (gpuBytes > usable(ceiling)) {
256	        if (params.gpuMemoryUtilization !== null && params.gpuMemoryUtilization !== undefined) {
257	            return result('incompatible', `Needs about ${gib(gpuBytes)} of GPU memory; gpuMemoryUtilization ${params.gpuMemoryUtilization} `
258	                + `gives vLLM about ${gib(usable(ceiling))}. Raise gpuMemoryUtilization or leave it empty.`, estimate, warnings);
259	        }
260	        const needed = Math.ceil((gpuBytes - usable(ceiling)) / GIB);
261	        return result('incompatible', `Needs about ${gib(gpuBytes)} of GPU memory for its weights and a KV cache for `
262	            + `${params.maxModelLen} tokens; vLLM can use about ${gib(usable(ceiling))} of this GPU. Reduce maxModelLen, `
263	            + `pick a smaller model, or offload weights to RAM with cpuOffloadGb (at least ${needed + (offloadBytes / GIB)} GiB; much slower).`,
264	        estimate, warnings);
265	    }
266	    const offloadNeeds = `Offloading ${gib(offloadBytes)} needs about ${gib(ramBytes)} of system RAM `
267	        + `(${VLLM_OFFLOAD_RAM_FACTOR} x the offload plus 3.0 GiB for vLLM, measured, plus 15 %)`;
268	    if (offloadBytes > 0 && memory.totalBytes && ramBytes > memory.totalBytes - ramFloor) {
269	        return result('incompatible', `${offloadNeeds}; this machine has ${gib(memory.totalBytes)} and ${gib(ramFloor)} must stay free. `
270	            + 'Lower cpuOffloadGb or pick a smaller model.', estimate, warnings);
271	    }
272	    if (memory.totalBytes && ramBytes > memory.totalBytes) {
273	        return result('incompatible', `Needs about ${gib(ramBytes)} of RAM; this machine has ${gib(memory.totalBytes)}.`, estimate, warnings);
274	    }
275	    // Busy now: the share does not fit in the free memory, or what is free
276	    // leaves vLLM less than its minimum share (a large GPU mostly in use).
277	    if (gpuMemoryUtilization < 0.1 || gpuMemoryUtilization * gpu.totalBytes > gpu.freeBytes - GPU_MARGIN_BYTES
278	        || gpuBytes > usable(gpuMemoryUtilization)) {
279	        return result('insufficient-now', `Needs about ${gib(gpuBytes)} of GPU memory; ${gib(gpu.freeBytes)} is free now`
280	            + `${otherGpuUsers(gpu)}.`, estimate, warnings);
281	    }
282	    if (offloadBytes > 0 && memory.availableBytes && ramBytes > memory.availableBytes - ramFloor) {
283	        return result('insufficient-now', `${offloadNeeds}; ${gib(memory.availableBytes)} is available now and ${gib(ramFloor)} `
284	            + 'must stay free for the desktop and other agents. Close other applications, lower cpuOffloadGb, or pick a smaller model.',
285	        estimate, warnings);
286	    }
287	    if (memory.availableBytes && ramBytes > memory.availableBytes - RAM_MARGIN_BYTES) {
288	        return result('insufficient-now', `Needs about ${gib(ramBytes)} of RAM; ${gib(memory.availableBytes)} is available now.`,
289	            estimate, warnings);
290	    }
291	    if (diskShortage(remainingDownloadBytes, disk)) {
292	        return result('insufficient-now', `The download needs ${gib(remainingDownloadBytes * 1.05)} of free disk; `
293	            + `${gib(disk.freeBytes)} is free.`, estimate, warnings);
294	    }
295	    return result('ok', null, estimate, warnings);
296	}
297	
298	// TabbyAPI with ExLlamaV3: all weights on the GPU, a KV cache of cacheSize
299	// tokens at cacheMode precision, and an estimated 640 MiB for the CUDA
300	// context and the activations of one prompt chunk.
301	const TABBY_OVERHEAD_BYTES = 640 * MIB;
302	const TABBY_CACHE_FACTOR = Object.freeze({ FP16: 1, Q8: 0.5, Q6: 0.375, Q4: 0.25 });
303	
304	export function admitTabbyApi({ model, source, params, gpu, memory, disk, remainingDownloadBytes = 0 }) {
305	    const size = source.size || 0;
306	    const cacheTokens = params.cacheSize ?? params.maxSeqLen;
307	    const kvBytes = Math.round((model.memory?.kvBytesPerToken || DEFAULT_KV_BYTES_PER_TOKEN) * cacheTokens
308	        * (TABBY_CACHE_FACTOR[params.cacheMode] ?? 1));
309	    // ExLlamaV3 keeps the input embedding in system RAM (measured with
310	    // Qwen3-8B EXL3: 4,141 MiB on the GPU for a 4,966 MiB snapshot).
311	    const embeddingBytes = Math.min(size, model.memory?.embeddingBytes || 0);
312	    const gpuWeightsBytes = size - embeddingBytes;
313	    const gpuBytes = gpuWeightsBytes + kvBytes + TABBY_OVERHEAD_BYTES;
314	    const usable = gpu.totalBytes * VLLM_USABLE_SHARE;
315	    const ramBytes = VLLM_RUNNER_RAM_BYTES + embeddingBytes;
316	    const estimate = { weightsBytes: size, gpuWeightsBytes, cpuWeightsBytes: embeddingBytes, kvBytes, gpuBytes, ramBytes,
317	        basis: 'snapshot size, KV cache for cacheSize at cacheMode, and an estimated overhead' };
318	    const warnings = ramWarning(ramBytes, memory);
319	    if (gpuBytes > usable) {
320	        return result('incompatible', `Needs about ${gib(gpuBytes)} of GPU memory for its weights and a ${cacheTokens}-token `
321	            + `${params.cacheMode} cache; about ${gib(usable)} of this GPU is usable. Lower maxSeqLen, use cacheMode Q4, `
322	            + 'or pick a smaller model.', estimate, warnings);
323	    }
324	    if (memory.totalBytes && ramBytes > memory.totalBytes) {
325	        return result('incompatible', `Needs about ${gib(ramBytes)} of RAM; this machine has ${gib(memory.totalBytes)}.`, estimate, warnings);
326	    }
327	    if (gpuBytes > gpu.freeBytes - GPU_MARGIN_BYTES) {
328	        return result('insufficient-now', `Needs about ${gib(gpuBytes)} of GPU memory; ${gib(gpu.freeBytes)} is free now`
329	            + `${otherGpuUsers(gpu)}.`, estimate, warnings);
330	    }
331	    if (memory.availableBytes && ramBytes > memory.availableBytes - RAM_MARGIN_BYTES) {
332	        return result('insufficient-now', `Needs about ${gib(ramBytes)} of RAM; ${gib(memory.availableBytes)} is available now.`,
333	            estimate, warnings);
334	    }
335	    if (diskShortage(remainingDownloadBytes, disk)) {
336	        return result('insufficient-now', `The download needs ${gib(remainingDownloadBytes * 1.05)} of free disk; `
337	            + `${gib(disk.freeBytes)} is free.`, estimate, warnings);
338	    }
339	    return result('ok', null, estimate, warnings);
340	}
341	
342	/**
343	 * The checks every runner shares, then the runner's own policy
344	 * (`runner.admit`), which sizes the estimate for how that runner uses memory.
345	 *
346	 * @param {{ runner, model, source, params, snapshot, remainingDownloadBytes? }} input
347	 * @returns {{ status: 'ok'|'incompatible'|'insufficient-now', reason, estimate, warnings }}
348	 */
349	export function admit({ runner, model, source, params, snapshot, remainingDownloadBytes = 0 }) {
350	    if (!runner.supported || typeof runner.admit !== 'function') {
351	        return result('incompatible', runner.unsupportedReason || `${runner.displayName} is not supported in this release.`, {});
352	    }
353	    if (!source) {
354	        return result('incompatible', `${model.displayName} has no ${runner.displayName} source.`, {});
355	    }
356	    const gpu = snapshot?.gpu;
357	    if (!gpu?.available) {
358	        return result('incompatible', gpu?.reason || 'No GPU is available to this agent.', {});
359	    }
360	    return runner.admit({
361	        model, source, params, gpu, memory: snapshot.memory || {}, disk: snapshot.disk, remainingDownloadBytes,
362	    });
363	}

