912	    let descriptor;
913	    try {
914	        descriptor = fsApi.openSync(
915	            temporary,
916	            fsApi.constants.O_WRONLY | fsApi.constants.O_CREAT | fsApi.constants.O_EXCL | fsApi.constants.O_NOFOLLOW,
917	            0o600,
918	        );
919	        fsApi.writeFileSync(descriptor, content);
920	        fsApi.fsyncSync(descriptor);
921	        fsApi.closeSync(descriptor);
922	        descriptor = undefined;
923	        beforeRename();
924	        fsApi.renameSync(temporary, target);
925	    } finally {
926	        if (descriptor !== undefined) fsApi.closeSync(descriptor);
927	        try { fsApi.unlinkSync(temporary); } catch (error) {
928	            if (error?.code !== 'ENOENT') throw error;
929	        }
930	    }
931	}
932	
933	/**
934	 * Host-only, per-workspace GPU grant record and generation files.
935	 *
936	 * @param {{ homeDirectory?: string, fsApi?: typeof fs }} [options]
937	 */
938	export function createGpuGrantStore({
939	    homeDirectory = os.homedir(),
940	    fsApi = fs,
941	} = {}) {
942	    const stateRoot = stateRootFor(homeDirectory);
943	    const directory = gpuGrantDirectory(homeDirectory);
944	
945	    function targetFor(identity) {
946	        return path.join(directory, `${exactIdentity(identity).instance}.json`);
947	    }
948	
949	    function instanceDirectory(identity) {
950	        return path.join(directory, exactIdentity(identity).instance);
951	    }
952	
953	    function assertConfined(identity) {
954	        return assertRouterBindingStateConfined(identity, { homeDirectory, fsApi });
955	    }
956	
957	    function normalizeAdmitted(value) {
958	        if (value === null) return null;
959	        if (!value || typeof value !== 'object' || Array.isArray(value)
960	            || JSON.stringify(Object.keys(value).sort()) !== JSON.stringify(['fingerprint', 'reason', 'state'])
961	            || !FINGERPRINT_RE.test(String(value.fingerprint))
962	            || !['active', 'stale', 'revoked'].includes(value.state)
963	            || (value.reason !== null && typeof value.reason !== 'string')) {
964	            throw stateError('Saved GPU grant has an invalid admitted wiring');
965	        }
966	        return Object.freeze({ fingerprint: value.fingerprint, state: value.state, reason: value.reason });
967	    }
968	
969	    function normalizeRecord(identity, record) {
970	        exactIdentity(identity);
971	        const keys = record && typeof record === 'object' ? Object.keys(record) : [];
972	        if (!record || typeof record !== 'object' || Array.isArray(record)
973	            || Object.getPrototypeOf(record) !== Object.prototype
974	            || !RECORD_KEYS.every((key) => keys.includes(key))
975	            || !keys.every((key) => RECORD_KEYS.includes(key) || OPTIONAL_RECORD_KEYS.includes(key))) {
976	            throw stateError('Saved GPU grant has an unsupported schema');
977	        }
978	        if (record.version !== GPU_GRANT_STATE_VERSION) {
979	            throw stateError(`Saved GPU grant version ${JSON.stringify(record.version)} is unsupported`);
980	        }
981	        if (record.instance !== identity.instance
982	            || record.pathHash !== identity.pathHash
983	            || record.workspaceRoot !== identity.workspaceRoot) {
984	            throw stateError('Saved GPU grant belongs to another workspace');
985	        }
986	        let decision;
987	        try {
988	            decision = normalizeGpuDecision({
989	                vendor: record.vendor,
990	                agents: record.agents,
991	                denied: record.denied,
992	                workspaceDenied: record.workspaceDenied,
993	            });
994	            if (Object.hasOwn(record, 'denied') && !record.denied.length) throw new Error('denied is written only when set');
995	            if (Object.hasOwn(record, 'workspaceDenied') && record.workspaceDenied !== true) {
996	                throw new Error('workspaceDenied is written only when set');
997	            }
998	        } catch (error) {
999	            throw stateError(`Saved GPU grant is invalid: ${error.message}`, error);
1000	        }
1001	        if (!decision) throw stateError('Saved GPU grant records no decision');
1002	        return Object.freeze({ ...decision, admitted: normalizeAdmitted(record.admitted) });
1003	    }
1004	
1005	    /** @returns {Readonly<object>|null} null when the workspace has no grant */
1006	    function read(identity) {
1007	        const target = targetFor(identity);
1008	        assertConfined(identity);
1009	        if (!assertPrivateDirectoryIfPresent(fsApi, stateRoot)
1010	            || !assertPrivateDirectoryIfPresent(fsApi, directory)) return null;
1011	        const bytes = readPrivateFile(fsApi, target, GPU_GRANT_STATE_MAX_BYTES, 'Saved GPU grant');
1012	        if (!bytes) return null;
1013	        let record;
1014	        try {
1015	            record = JSON.parse(bytes.toString('utf8'));
1016	        } catch (error) {
1017	            throw stateError(`Saved GPU grant is not valid JSON: ${target}`, error);
1018	        }
1019	        return normalizeRecord(identity, record);
1020	    }
1021	
1022	    function write(identity, grant, lock, { admitted = null } = {}) {
1023	        exactIdentity(identity);
1024	        assertLock(identity, lock);
1025	        const normalized = normalizeGpuDecision(grant);
1026	        if (!normalized) throw stateError('Saving a GPU grant requires a grant, a deny or a workspace deny');
1027	        const admittedValue = normalizeAdmitted(admitted);
1028	        assertConfined(identity);
1029	        ensurePrivateDirectory(fsApi, stateRoot);
1030	        ensurePrivateDirectory(fsApi, directory);
1031	        assertConfined(identity);
1032	        const record = {
1033	            version: GPU_GRANT_STATE_VERSION,
1034	            instance: identity.instance,
1035	            pathHash: identity.pathHash,
1036	            workspaceRoot: identity.workspaceRoot,
1037	            vendor: normalized.vendor,
1038	            agents: normalized.agents,
1039	            admitted: admittedValue,
1040	            ...(normalized.denied.length ? { denied: normalized.denied } : {}),
1041	            ...(normalized.workspaceDenied ? { workspaceDenied: true } : {}),
1042	        };
1043	        writePrivateFileAtomically(fsApi, directory, targetFor(identity), `${JSON.stringify(record)}\n`, () => {
1044	            lock.assertHeld(identity.instance);
1045	            assertConfined(identity);
1046	        });
1047	        return Object.freeze({ ...normalized, admitted: admittedValue });
1048	    }
1049	
1050	    function clear(identity, lock) {
1051	        exactIdentity(identity);
1052	        assertLock(identity, lock);
1053	        assertConfined(identity);
1054	        if (!assertPrivateDirectoryIfPresent(fsApi, stateRoot)
1055	            || !assertPrivateDirectoryIfPresent(fsApi, directory)) return false;
1056	        const target = targetFor(identity);
1057	        let stat;
1058	        try {
1059	            stat = fsApi.lstatSync(target);
1060	        } catch (error) {
1061	            if (error?.code === 'ENOENT') return false;
1062	            throw stateError(`Unable to inspect saved GPU grant: ${target}`, error);
1063	        }
1064	        if (!stat.isFile() && !stat.isSymbolicLink()) {
1065	            throw stateError(`Refusing to remove a non-regular GPU grant state path: ${target}`);
1066	        }
1067	        fsApi.unlinkSync(target);
1068	        return true;
1069	    }
1070	
1071	    /** Put back exactly the record captured before a failed mutation. */
1072	    function restore(identity, previous, lock) {
1073	        if (previous) write(identity, previous, lock, { admitted: previous.admitted ?? null });
1074	        else clear(identity, lock);
1075	    }
1076	
1077	    /**
1078	     * A kept wiring binds host driver files and device nodes that a driver
1079	     * package upgrade can remove while the running Box still pins them. They
1080	     * are checked before anything destructive, so a replacement is refused
1081	     * instead of removing the old Box and then failing to create the new one.
1082	     */
1083	    function assertKeptHostSources(wiring) {
1084	        const changed = (item, detail) => stateError(
1085	            `GPU wiring ${wiring.fingerprint} binds ${item}, which ${detail}; the host driver changed. `
1086	            + 'Run `ploinky restart` to rediscover the driver and regenerate the wiring.',
1087	        );
1088	        for (const mount of wiring.mounts) {
1089	            if (mount.destination === BOX_GPU_MARKER_PATH || mount.destination === BOX_GPU_CDI_SPEC_PATH) continue;
1090	            let stat;
1091	            try {
1092	                stat = fsApi.statSync(mount.source);
1093	                fsApi.accessSync(mount.source, fs.constants.R_OK);
1094	            } catch (error) {
1095	                throw changed(mount.source, `is missing or unreadable (${error.code || error.message})`);
1096	            }
1097	            if (!stat.isFile()) throw changed(mount.source, 'is not a regular file');
1098	        }
1099	        for (const device of wiring.devices) {
1100	            let stat;
1101	            try {
1102	                stat = fsApi.statSync(device);
1103	            } catch (error) {
1104	                throw changed(device, `is missing (${error.code || error.message})`);
1105	            }
1106	            if (!stat.isCharacterDevice()) throw changed(device, 'is not a character device');
1107	        }
1108	    }
1109	
1110	    /**
1111	     * Write a wiring's spec and marker into its content-addressed generation
1112	     * directory. An existing generation must hold byte-identical files. A wiring
1113	     * reconstructed from a Box (kept across a replacement) carries no file
1114	     * contents: its generation must already exist, which pruning guarantees
1115	     * while that Box exists, and it is only verified here.
1116	     */
1117	    function materialize(identity, wiring, lock) {
1118	        if (!wiring) return;
1119	        exactIdentity(identity);
1120	        assertLock(identity, lock);
1121	        assertConfined(identity);
1122	        const generation = gpuGenerationDirectory(identity, wiring.fingerprint, homeDirectory);
1123	        if (!Array.isArray(wiring.files)) {
1124	            for (const mount of wiring.mounts) {
1125	                if (mount.destination !== BOX_GPU_MARKER_PATH && mount.destination !== BOX_GPU_CDI_SPEC_PATH) continue;
1126	                if (path.dirname(mount.source) !== generation) {
1127	                    throw stateError(`GPU wiring file is outside its generation directory: ${mount.source}`);
1128	                }
1129	                if (!readPrivateFile(fsApi, mount.source, GPU_GRANT_STATE_MAX_BYTES, 'GPU wiring file')) {
1130	                    throw stateError(
1131	                        `GPU wiring file ${mount.source} is missing; run \`ploinky gpu grant\` or `
1132	                        + '`ploinky restart` to regenerate the wiring',
1133	                    );
1134	                }
1135	            }
1136	            assertKeptHostSources(wiring);
1137	            return;
1138	        }
1139	        for (const target of [stateRoot, directory, instanceDirectory(identity), generation]) {
1140	            ensurePrivateDirectory(fsApi, target);
1141	        }
1142	        assertConfined(identity);
1143	        for (const file of wiring.files) {
1144	            if (path.dirname(file.path) !== generation) {
1145	                throw stateError(`GPU wiring file escaped its generation directory: ${file.path}`);
1146	            }
1147	            const existing = readPrivateFile(fsApi, file.path, GPU_GRANT_STATE_MAX_BYTES, 'GPU wiring file');
1148	            if (existing) {
1149	                if (!existing.equals(Buffer.from(file.content))) {
1150	                    throw stateError(`GPU wiring file does not match its fingerprint: ${file.path}`);
1151	                }
1152	                continue;
1153	            }
1154	            writePrivateFileAtomically(fsApi, generation, file.path, file.content, () => {
1155	                lock.assertHeld(identity.instance);
1156	                assertConfined(identity);
1157	            });
1158	        }
1159	    }
1160	
1161	    /** Remove every generation directory of this workspace except `keep`. */
1162	    function prune(identity, keep, lock) {
1163	        exactIdentity(identity);
1164	        assertLock(identity, lock);
1165	        assertConfined(identity);
1166	        const root = instanceDirectory(identity);
1167	        if (!assertPrivateDirectoryIfPresent(fsApi, stateRoot)
1168	            || !assertPrivateDirectoryIfPresent(fsApi, directory)
1169	            || !assertPrivateDirectoryIfPresent(fsApi, root)) return [];
1170	        const kept = new Set([...keep].filter(Boolean));
1171	        const removed = [];
1172	        for (const entry of fsApi.readdirSync(root)) {
1173	            if (kept.has(entry)) continue;
1174	            const target = path.join(root, entry);
1175	            const stat = fsApi.lstatSync(target);
1176	            if (!FINGERPRINT_RE.test(entry) || stat.isSymbolicLink() || !stat.isDirectory()) {
1177	                throw stateError(`Unexpected entry in GPU grant generations: ${target}`);
1178	            }
1179	            fsApi.rmSync(target, { recursive: true, force: true });
1180	            removed.push(entry);
1181	        }
1182	        if (kept.size === 0 && fsApi.readdirSync(root).length === 0) fsApi.rmdirSync(root);
1183	        return removed;
1184	    }
1185	
1186	    return Object.freeze({
1187	        homeDirectory: path.resolve(homeDirectory),
1188	        directory,
1189	        pathFor: targetFor,
1190	        assertConfined,
1191	        validateRecord: normalizeRecord,
1192	        read,
1193	        write,
1194	        clear,
1195	        restore,
1196	        materialize,
1197	        prune,
1198	    });
1199	}
