  8	
  9	// Every runner is an adapter (llamaServer.mjs shows the full shape): identity,
 10	// the weight format it reads, its loopback port and per-start key, its
 11	// parameter schema and form metadata, detection, the start-up pipeline, the
 12	// chat model name, its admission policy and its log-report parser. The
 13	// controller has no per-runner branches; adding a runner adds an adapter here.
 14	// LM Studio is for internal use only, behind an operator switch (runners plan
 15	// I9, Phase R7; DS000).
 16	export const RUNNERS = Object.freeze({
 17	    'llama.cpp': llamaCppRunner,
 18	    'ik_llama.cpp': ikLlamaCppRunner,
 19	    ollama: ollamaRunner,
 20	    vllm: vllmRunner,
 21	    tabbyapi: tabbyApiRunner,
 22	    lmstudio: lmStudioRunner
 23	});
 24	
 25	export function getRunner(id) {
 26	    if (typeof id !== 'string' || !Object.hasOwn(RUNNERS, id)) {
 27	        throw codedError('unknown_runner', `Unknown runner: ${String(id)}`, { runner: id });
 28	    }
 29	    return RUNNERS[id];
 30	}
 31	
 32	/** The loopback port of every supported runner; two runners never share one. */
 33	export function defaultPorts(runners = RUNNERS) {
 34	    const ports = {};
 35	    const owners = new Map();
 36	    for (const runner of Object.values(runners)) {
 37	        if (!runner.supported) continue;
 38	        if (!Number.isInteger(runner.port)) throw new Error(`Runner ${runner.id} has no port`);
 39	        if (owners.has(runner.port)) {
 40	            throw new Error(`Runners ${owners.get(runner.port)} and ${runner.id} both use port ${runner.port}`);
 41	        }
 42	        owners.set(runner.port, runner.id);
 43	        ports[runner.id] = runner.port;
 44	    }
 45	    return Object.freeze(ports);
 46	}
 47	
 48	/** What the overview and the dashboard learn about each runner. */
 49	export function runnerSummary(runner) {
 50	    const { id, displayName, weightFormat, pinnedVersion, supported, paramSchema } = runner;
 51	    return {
 52	        id, displayName, weightFormat, pinnedVersion, supported, paramSchema,
 53	        basicParams: runner.basicParams || [],
 54	        moeParams: runner.moeParams || [],
 55	    };
 56	}
