  1	// The llama-server family: llama.cpp and ik_llama.cpp serve the same GGUF
  2	// files with the same OpenAI-compatible server and the same parameters, but
  3	// their command lines differ. A dialect names the differences; everything
  4	// else, the readiness probes included, is shared.
  5	
  6	import { spawnSync as realSpawnSync } from 'node:child_process';
  7	
  8	import { admitLlamaServer } from '../controller/admission.mjs';
  9	import { defaultThreads, physicalCoreCount } from '../controller/hardware.mjs';
 10	import { parseRunnerReport } from '../controller/runnerProcess.mjs';
 11	import {
 12	    ParamError,
 13	    assertAbsolutePath,
 14	    assertApiKey,
 15	    assertPort,
 16	    codedError,
 17	    deepFreeze,
 18	    probeEnv,
 19	    probeVersion,
 20	    recommendedFor,
 21	    validateParams
 22	} from './params.mjs';
 23	
 24	const NVIDIA_LIB_DIR = '/usr/local/nvidia/lib64';
 25	const KV_CACHE_TYPES = ['f16', 'q8_0', 'q4_0'];
 26	
 27	export const LLAMA_SERVER_PARAM_SCHEMA = deepFreeze({
 28	    type: 'object',
 29	    additionalProperties: false,
 30	    properties: {
 31	        ctxSize: {
 32	            type: 'integer', minimum: 512, maximum: 131072, default: 16384,
 33	            title: 'Context size',
 34	            description: 'Total context window in tokens, shared by all parallel slots.'
 35	        },
 36	        nGpuLayers: {
 37	            type: 'integer', minimum: 0, maximum: 999, default: 99,
 38	            title: 'GPU layers',
 39	            description: 'Number of model layers offloaded to the GPU (99 or more means all).'
 40	        },
 41	        nCpuMoe: {
 42	            type: 'integer', minimum: 0, maximum: 256, default: 0,
 43	            title: 'CPU MoE layers',
 44	            description: 'Number of layers whose MoE expert weights stay in CPU RAM (0 keeps all on GPU).'
 45	        },
 46	        flashAttn: {
 47	            type: 'string', enum: ['auto', 'on', 'off'], default: 'auto',
 48	            title: 'Flash attention',
 49	            description: 'Flash attention mode.'
 50	        },
 51	        cacheTypeK: {
 52	            type: 'string', enum: KV_CACHE_TYPES, default: 'f16',
 53	            title: 'K cache type',
 54	            description: 'Quantization type of the KV cache keys.'
 55	        },
 56	        cacheTypeV: {
 57	            type: 'string', enum: KV_CACHE_TYPES, default: 'f16',
 58	            title: 'V cache type',
 59	            description: 'Quantization type of the KV cache values.'
 60	        },
 61	        threads: {
 62	            type: ['integer', 'null'], minimum: 1, maximum: 256, default: null,
 63	            title: 'CPU threads',
 64	            description: 'Number of CPU threads for generation; empty uses the physical CPU cores minus 2.'
 65	        },
 66	        parallel: {
 67	            type: 'integer', minimum: 1, maximum: 16, default: 1,
 68	            title: 'Parallel slots',
 69	            description: 'Number of concurrent request slots; above 1 the slots share one unified KV cache.'
 70	        },
 71	        batchSize: {
 72	            type: 'integer', minimum: 32, maximum: 8192, default: 2048,
 73	            title: 'Batch size',
 74	            description: 'Logical maximum batch size for prompt processing.'
 75	        },
 76	        ubatchSize: {
 77	            type: 'integer', minimum: 32, maximum: 4096, default: 512,
 78	            title: 'Micro-batch size',
 79	            description: 'Physical maximum batch size; must not exceed the batch size.'
 80	        },
 81	        mlock: {
 82	            type: 'boolean', default: false,
 83	            title: 'Lock model in RAM',
 84	            description: 'Lock model weights in RAM so they cannot be swapped out.'
 85	        },
 86	        noMmap: {
 87	            type: 'boolean', default: false,
 88	            title: 'Disable mmap',
 89	            description: 'Read the model into memory instead of memory-mapping the file.'
 90	        },
 91	        chatTemplateKwargs: {
 92	            type: 'object',
 93	            additionalProperties: false,
 94	            title: 'Chat template arguments',
 95	            description: 'Extra arguments passed to the Jinja chat template.',
 96	            properties: {
 97	                reasoning_effort: {
 98	                    type: 'string', enum: ['low', 'medium', 'high'],
 99	                    title: 'Reasoning effort',
100	                    description: 'Reasoning effort hint for models whose template supports it.'
101	                }
102	            }
103	        }
104	    }
105	});
106	
107	function assertModelId(model) {
108	    if (typeof model?.id !== 'string' || model.id.length === 0) {
109	        throw codedError('invalid_launch', 'model.id must be a non-empty string', { field: 'model.id' });
110	    }
111	    return model.id;
112	}
113	
114	/**
115	 * A llama-server runner.
116	 *
117	 * dialect.quietArgs      flags that turn off the web UI and set the log level
118	 * dialect.unifiedKv      whether parallel slots share one KV cache (--kv-unified)
119	 * dialect.loadArgs(v)    flags for mlock/noMmap
120	 * dialect.jinja(model)   whether to pass --jinja
121	 * dialect.parseVersion   the version from `--version` output, or null
122	 *
123	 * cpuCores() counts the physical cores for the default --threads; it is read
124	 * once, on the first launch.
125	 */
126	export function createLlamaServerRunner({ id, displayName, executable, pinnedVersion, port, dialect, cpuCores = physicalCoreCount }) {
127	    const paramSchema = LLAMA_SERVER_PARAM_SCHEMA;
128	    let autoThreads = null;
129	    // The servers default to few threads; physical cores minus 2 is faster
130	    // here and leaves room for the agent and the host (runners plan, I2).
131	    // An admin-set value wins; the stored parameters keep "empty".
132	    const threadsFor = (values) => values.threads ?? (autoThreads ??= defaultThreads(cpuCores()));
133	
134	    function normalizeParams(params = {}, { model } = {}) {
135	        const values = validateParams(paramSchema, params, { defaults: recommendedFor(model, id) });
136	        if (values.ubatchSize > values.batchSize) {
137	            throw new ParamError('ubatchSize', `must be <= batchSize (${values.batchSize})`);
138	        }
139	        return values;
140	    }
141	
142	    function describeContext(params = {}, { model } = {}) {
143	        const { ctxSize, parallel } = normalizeParams(params, { model });
144	        // A unified KV cache lets every slot use the whole context; otherwise
145	        // each slot gets an equal share of it.
146	        const perRequestContext = dialect.unifiedKv ? ctxSize : Math.floor(ctxSize / parallel);
147	        return { totalContext: ctxSize, perRequestContext, parallel, kvUnified: dialect.unifiedKv && parallel > 1 };
148	    }
149	
150	    function detect({ spawnSync = realSpawnSync } = {}) {
151	        return probeVersion({
152	            spawnSync,
153	            executable,
154	            args: ['--version'],
155	            env: probeEnv({ LD_LIBRARY_PATH: NVIDIA_LIB_DIR }),
156	            parse: dialect.parseVersion,
157	            pinnedVersion
158	        });
159	    }
160	
161	    function tuningArgs(values) {
162	        const args = ['--ctx-size', values.ctxSize, '--n-gpu-layers', values.nGpuLayers];
163	        if (values.nCpuMoe > 0) {
164	            args.push('--n-cpu-moe', values.nCpuMoe);
165	        }
166	        args.push('--flash-attn', values.flashAttn);
167	        args.push('--cache-type-k', values.cacheTypeK, '--cache-type-v', values.cacheTypeV);
168	        args.push('--threads', threadsFor(values));
169	        args.push('-np', values.parallel);
170	        if (dialect.unifiedKv && values.parallel > 1) {
171	            args.push('--kv-unified');
172	        }
173	        args.push('--batch-size', values.batchSize, '--ubatch-size', values.ubatchSize);
174	        return args;
175	    }
176	
177	    function extraArgs(values, model) {
178	        const args = [...dialect.loadArgs(values)];
179	        if (values.chatTemplateKwargs) {
180	            args.push('--chat-template-kwargs', JSON.stringify(values.chatTemplateKwargs));
181	        }
182	        if (dialect.jinja(model)) {
183	            args.push('--jinja');
184	        }
185	        return args;
186	    }
187	
188	    function buildLaunch({ artifactPath, params, port: launchPort, apiKey, model } = {}) {
189	        const values = normalizeParams(params, { model });
190	        const args = [
191	            '-m', assertAbsolutePath(artifactPath, 'artifactPath'),
192	            '--host', '127.0.0.1',
193	            '--port', assertPort(launchPort),
194	            '--api-key', assertApiKey(apiKey),
195	            ...dialect.quietArgs,
196	            '--alias', assertModelId(model),
197	            ...tuningArgs(values),
198	            ...extraArgs(values, model)
199	        ];
200	        return { command: executable, args: args.map(String), env: { LD_LIBRARY_PATH: NVIDIA_LIB_DIR } };
201	    }
202	
203	    // /health answers once the model is loaded (llama.cpp returns 503 while it
204	    // loads; ik_llama.cpp accepts the connection and answers only then, so each
205	    // probe's own timeout keeps polling); /v1/models then answers with the key.
206	    async function start(ctx) {
207	        const process = ctx.launch(ctx.runner.buildLaunch({
208	            artifactPath: ctx.weights.path, params: ctx.params, port: ctx.port, apiKey: ctx.apiKey, model: ctx.model,
209	        }));
210	        const base = `http://127.0.0.1:${ctx.port}`;
211	        await ctx.waitForHttp(`${base}/health`, { process });
212	        await ctx.waitForHttp(`${base}/v1/models`, { headers: { authorization: `Bearer ${ctx.apiKey}` }, process });
213	        return {};
214	    }
215	
216	    return Object.freeze({
217	        id,
218	        displayName,
219	        weightFormat: 'gguf',
220	        pinnedVersion,
221	        supported: true,
222	        executable,
223	        port,
224	        apiKey: true,
225	        paramSchema,
226	        // Shown outside "Advanced" in the Run form; nCpuMoe only for MoE models.
227	        basicParams: Object.freeze(['ctxSize', 'nCpuMoe']),
228	        moeParams: Object.freeze(['nCpuMoe']),
229	        normalizeParams,
230	        describeContext,
231	        detect,
232	        buildLaunch,
233	        start,
234	        // --alias makes the model id the name the server answers to.
235	        chatModel: (deployment) => deployment.modelId,
236	        admit: admitLlamaServer,
237	        parseReport: parseRunnerReport
238	    });
239	}

