138	        }
139	        return values;
140	    }
141	
142	    function describeContext(params = {}, { model } = {}) {
143	        const { ctxSize, parallel } = normalizeParams(params, { model });
144	        // A unified KV cache lets every slot use the whole context; otherwise
145	        // each slot gets an equal share of it.
146	        const perRequestContext = dialect.unifiedKv ? ctxSize : Math.floor(ctxSize / parallel);
