188	    function buildLaunch({ artifactPath, params, port: launchPort, apiKey, model } = {}) {
189	        const values = normalizeParams(params, { model });
190	        const args = [
191	            '-m', assertAbsolutePath(artifactPath, 'artifactPath'),
192	            '--host', '127.0.0.1',
193	            '--port', assertPort(launchPort),
194	            '--api-key', assertApiKey(apiKey),
195	            ...dialect.quietArgs,
196	            '--alias', assertModelId(model),
197	            ...tuningArgs(values),
198	            ...extraArgs(values, model)
199	        ];
200	        return { command: executable, args: args.map(String), env: { LD_LIBRARY_PATH: NVIDIA_LIB_DIR } };
201	    }
202	
203	    // /health answers once the model is loaded (llama.cpp returns 503 while it
204	    // loads; ik_llama.cpp accepts the connection and answers only then, so each
205	    // probe's own timeout keeps polling); /v1/models then answers with the key.
206	    async function start(ctx) {
207	        const process = ctx.launch(ctx.runner.buildLaunch({
208	            artifactPath: ctx.weights.path, params: ctx.params, port: ctx.port, apiKey: ctx.apiKey, model: ctx.model,
209	        }));
210	        const base = `http://127.0.0.1:${ctx.port}`;
211	        await ctx.waitForHttp(`${base}/health`, { process });
212	        await ctx.waitForHttp(`${base}/v1/models`, { headers: { authorization: `Bearer ${ctx.apiKey}` }, process });
213	        return {};
214	    }
215	
216	    return Object.freeze({
217	        id,
218	        displayName,
219	        weightFormat: 'gguf',
220	        pinnedVersion,
221	        supported: true,
222	        executable,
223	        port,
224	        apiKey: true,
225	        paramSchema,
226	        // Shown outside "Advanced" in the Run form; nCpuMoe only for MoE models.
227	        basicParams: Object.freeze(['ctxSize', 'nCpuMoe']),
228	        moeParams: Object.freeze(['nCpuMoe']),
229	        normalizeParams,
230	        describeContext,
231	        detect,
232	        buildLaunch,
233	        start,
234	        // --alias makes the model id the name the server answers to.
235	        chatModel: (deployment) => deployment.modelId,
236	        admit: admitLlamaServer,
237	        parseReport: parseRunnerReport
238	    });
239	}

