#include <cstdio>
#include <cuda_runtime.h>
static void meminfo(const char* tag){
  FILE* f=fopen("/proc/meminfo","r"); char k[64]; long v; char u[8]; long tot=0,fr=0,av=0,ca=0,buf=0;
  while(fscanf(f,"%63s %ld %7s",k,&v,u)>=2){ if(!strcmp(k,"MemTotal:"))tot=v; else if(!strcmp(k,"MemFree:"))fr=v; else if(!strcmp(k,"MemAvailable:"))av=v; else if(!strcmp(k,"Cached:"))ca=v; else if(!strcmp(k,"Buffers:"))buf=v; }
  fclose(f); printf("[%s] meminfo GiB: MemTotal %.2f MemFree %.2f MemAvailable %.2f Cached %.2f Buffers %.2f\n",tag,tot/1048576.0,fr/1048576.0,av/1048576.0,ca/1048576.0,buf/1048576.0);
}
#include <cstring>
int main(){
  int drv=0, rt=0; cudaDriverGetVersion(&drv); cudaRuntimeGetVersion(&rt);
  printf("driver API %d, runtime %d\n", drv, rt);
  meminfo("before context");
  cudaDeviceProp p; cudaError_t e=cudaGetDeviceProperties(&p,0); if(e){printf("err %s\n",cudaGetErrorString(e));return 1;}
  printf("name=%s cc=%d.%d integrated=%d totalGlobalMem=%.2f GiB\n",p.name,p.major,p.minor,p.integrated,p.totalGlobalMem/1073741824.0);
  printf("pageableMemoryAccess=%d pageableMemoryAccessUsesHostPageTables=%d concurrentManagedAccess=%d canUseHostPointerForRegisteredMem=%d hostNativeAtomicSupported=%d unifiedAddressing=%d managedMemory=%d directManagedMemAccessFromHost=%d\n",
    p.pageableMemoryAccess,p.pageableMemoryAccessUsesHostPageTables,p.concurrentManagedAccess,p.canUseHostPointerForRegisteredMem,p.hostNativeAtomicSupported,p.unifiedAddressing,p.managedMemory,p.directManagedMemAccessFromHost);
  size_t fr=0,tot=0; cudaMemGetInfo(&fr,&tot);
  printf("cudaMemGetInfo: free=%.2f GiB total=%.2f GiB\n",fr/1073741824.0,tot/1073741824.0);
  meminfo("after context");
  return 0;
}
EOF
