import json,sys,re,collections
repo=sys.argv[1]
try: d=json.load(open('hf.json'))
except Exception as e: print(repo,'ERR',e); sys.exit()
if isinstance(d,dict): print(repo,'->',d.get('error')); sys.exit()
files=[f for f in d if f.get('type')=='file']
g=collections.defaultdict(int); cnt=collections.Counter()
for f in files:
    p=f['path']; s=f.get('lfs',{}).get('size') or f.get('size',0)
    if p.endswith('.gguf') or p.endswith('.safetensors'):
        key=re.sub(r'-\d{5}-of-\d{5}','',p)
        g[key]+=s; cnt[key]+=1
sel=[(k,v,cnt[k]) for k,v in g.items() if re.search(r'(mxfp4|MXFP4|Q8_0|Q4_K_M|UD-Q4_K_XL|safetensors)',k)]
tot=sum(v for k,v in g.items())
print(f"{repo}: {len(files)} files")
for k,v,c in sorted(sel,key=lambda x:x[1])[:6]: print(f"   {k}  {v/1e9:.1f} GB  parts={c}")
EOF
done

