1	// Where each kind of weights lives and how it is pinned, inspected, fetched
2	// and deleted. A source's `type` selects its store: `huggingface` is one GGUF
3	// file, or every shard of a split GGUF, that the controller downloads before
4	// the runner starts; `ollama` is a
5	// library tag that the Ollama runner pulls itself once it is running;
6	// `hf-snapshot` is a directory of files (safetensors for vLLM, EXL3 for
7	// TabbyAPI) that the controller downloads file by file.
8	//
9	// Every store has: `type`; `fetchedBy` ('controller' or 'runner');
10	// `key(source)`, the artifact identity used for "in use" checks, so runners
11	// that read the same file share it; `isPinned(source)`; `state(source)`;
12	// `remove(source)`; `pin(source)` and `carryPin(next, previous)` for Add and
13	// Update model; and `fetch(...)` when the controller fetches.
14	
15	import fs from 'node:fs';
16	import path from 'node:path';
17	
18	import { LocalLlmError } from '../errors.mjs';
19	import {
20	    artifactPaths,
21	    downloadSnapshotFile,
22	    inspectSnapshotFile,
23	    resolveHuggingFaceSnapshot,
24	    snapshotPaths,
25	} from './downloader.mjs';
26	import { splitGgufFiles, splitGgufName } from './catalog.mjs';
27	import { deleteOllamaModel, deleteOllamaPartials, partialPullBytes, readOllamaManifest } from './ollamaStore.mjs';
28	
29	export function createWeightStores({
30	    dataDir,
31	    env,
32	    hfBaseUrl,
33	    inspect,
34	    download,
35	    remove,
36	    resolveHf,
37	    state,
38	    save,
39	    // The artifact of the job that is running now, or null.
40	    activeArtifact,
41	    downloadSnapshot = downloadSnapshotFile,
42	    inspectSnapshot = inspectSnapshotFile,
43	    resolveSnapshot = resolveHuggingFaceSnapshot,
44	}) {
45	    const ggufRoot = path.join(dataDir, 'models', 'gguf');
46	    const ollamaModels = path.join(dataDir, 'models', 'ollama');
47	    const hfRoot = path.join(dataDir, 'models', 'hf');
48	
49	    // One file, or every shard of a split GGUF (DS002), each as the downloader's artifact.
50	    const filesOf = (source) => (source.shards
51	        ? source.shards.map((shard) => ({ ...source, shards: undefined, file: shard.file, size: shard.size, sha256: shard.sha256 }))
52	        : [source]);
53	
54	    const huggingface = Object.freeze({
55	        type: 'huggingface',
56	        fetchedBy: 'controller',
57	        // A split GGUF is one artifact: its commit, first shard and shard count.
58	        key: (source) => `gguf:${source.repo}@${source.commit}/${source.file}${source.shards ? `#${source.shards.length}` : ''}`,
59	        isPinned: (source) => Boolean(source.commit) && (!splitGgufName(source.file) || Array.isArray(source.shards)),
60	        async state(source) {
61	            if (!huggingface.isPinned(source)) return { state: 'unpinned', bytes: 0, total: null };
62	            if (!source.shards) {
63	                const inspected = await inspect({ root: ggufRoot, artifact: source });
64	                return { ...inspected, total: source.size };
65	            }
66	            // The set is complete only when every shard is; bytes are counted over the set.
67	            const shards = [];
68	            for (const file of filesOf(source)) shards.push(await inspect({ root: ggufRoot, artifact: file }));
69	            const bytes = shards.reduce((sum, shard) => sum + (shard.bytes || 0), 0);
70	            const all = (value) => shards.every((shard) => shard.state === value);
71	            const stateOf = all('complete') ? 'complete' : all('absent') ? 'absent' : 'partial';
72	            return { state: stateOf, bytes, total: source.size, ...(source.shards ? { shards: shards.length } : {}) };
73	        },
74	        async fetch({ artifact, signal, onProgress }) {
75	            // Shard by shard into one directory; progress counts the whole set.
76	            let done = 0;
77	            let transferred = 0;
78	            let first = null;
79	            const files = [];
80	            for (const file of filesOf(artifact)) {
81	                const offset = done;
82	                const result = await download({
83	                    artifact: file,
84	                    root: ggufRoot,
85	                    token: env.HF_TOKEN || '',
86	                    baseUrl: hfBaseUrl,
87	                    onProgress: (progress) => onProgress?.({
88	                        ...progress,
89	                        bytes: offset + (progress.bytes || 0),
90	                        total: artifact.size,
91	                        transferred: transferred + (progress.transferred || 0),
92	                    }),
93	                    signal,
94	                });
95	                first ??= result.path;
96	                files.push(result.path);
97	                done += file.size;
98	                transferred += result.bytesTransferred || 0;
99	            }
100	            return { path: first, files, bytes: artifact.size, bytesTransferred: transferred };
101	        },
102	        async remove(source) {
103	            if (!source.commit) return 0;
104	            let freed = 0;
105	            for (const file of filesOf(source)) freed += await remove({ root: ggufRoot, artifact: file });
106	            return freed;
107	        },
108	        // Pinning reads Hugging Face metadata only; no weights are downloaded.
109	        async pin(source) {
110	            if (huggingface.isPinned(source)) return source;
111	            const resolve = (file, revision) => resolveHf({
112	                repo: source.repo,
113	                file,
114	                revision,
115	                token: env.HF_TOKEN || '',
116	                baseUrl: hfBaseUrl,
117	            });
118	            const resolved = await resolve(source.file, source.revision || 'main');
119	            const files = splitGgufFiles(source.file);
120	            if (!files) return { ...source, commit: resolved.commit, size: resolved.size, sha256: resolved.sha256 };
121	            // Every shard at the same commit.
122	            const shards = [{ file: source.file, size: resolved.size, sha256: resolved.sha256 }];
123	            for (const file of files.slice(1)) {
124	                const next = await resolve(file, resolved.commit);
125	                shards.push({ file, size: next.size, sha256: next.sha256 });
126	            }
127	            return { ...source, commit: resolved.commit, size: shards.reduce((sum, shard) => sum + shard.size, 0), shards };
128	        },
129	        // An update keeps the pinned commit while repository, file and
130	        // revision are unchanged; it never silently re-resolves a branch.
131	        carryPin(next, previous) {
132	            if (next.commit || previous?.type !== 'huggingface' || !previous.commit) return next;
133	            if (next.repo !== previous.repo || next.file !== previous.file || next.revision !== previous.revision) return next;
134	            return previous.shards
135	                ? { ...next, commit: previous.commit, size: previous.size, shards: previous.shards }
136	                : { ...next, commit: previous.commit, size: previous.size, sha256: previous.sha256 };
137	        },
138	        paths: (source) => artifactPaths({ root: ggufRoot, artifact: filesOf(source)[0] }),
139	    });
140	
141	    function manifestOrNull(tag) {
142	        try {
143	            return readOllamaManifest(ollamaModels, tag);
144	        } catch (error) {
145	            if (error?.code === 'invalid_manifest') return null;
146	            throw error;
147	        }
148	    }
149	
150	    function pulls() {
151	        const current = state();
152	        current.ollamaPulls ||= {};
153	        return current.ollamaPulls;
154	    }
155	
156	    const ollama = Object.freeze({
157	        type: 'ollama',
158	        fetchedBy: 'runner',
159	        key: (source) => `ollama:${source.tag}`,
160	        isPinned: () => true,
161	        async state(source) {
162	            const manifest = manifestOrNull(source.tag);
163	            if (manifest?.complete) return { state: 'complete', bytes: manifest.size, total: manifest.size };
164	            const partial = partialPullBytes(ollamaModels, state().ollamaPulls?.[source.tag] || []);
165	            return { state: partial ? 'partial' : 'absent', bytes: partial, total: source.size ?? null };
166	        },
167	        // Ollama tags can share blobs: never remove a partial another tag's
168	        // pull claims, and refuse while another tag's running pull has
169	        // reported a blob this deletion would touch.
170	        async remove(source) {
171	            const recorded = pulls();
172	            const claimedByOthers = Object.entries(recorded)
173	                .filter(([tag]) => tag !== source.tag)
174	                .flatMap(([, digests]) => digests);
175	            const running = activeArtifact();
176	            const activeTag = running?.type === 'ollama' ? running.tag : null;
177	            if (activeTag && activeTag !== source.tag) {
178	                const touched = new Set([
179	                    ...(recorded[source.tag] || []),
180	                    ...(manifestOrNull(source.tag)?.blobs.map((blob) => blob.digest) || []),
181	                ]);
182	                if ((recorded[activeTag] || []).some((digest) => touched.has(digest))) {
183	                    throw new LocalLlmError('in_use', `The running ${activeTag} download uses some of these files; `
184	                        + 'wait for it to finish or cancel it first.');
185	                }
186	            }
187	            const freed = deleteOllamaModel(ollamaModels, source.tag)
188	                + deleteOllamaPartials(ollamaModels, {
189	                    digests: recorded[source.tag] || [],
190	                    claimedByOthers,
191	                    keepOrphans: activeTag !== null,
192	                });
193	            if (recorded[source.tag]) {
194	                delete recorded[source.tag];
195	                save();
196	            }
197	            return freed;
198	        },
199	        pin: async (source) => source,
200	        carryPin: (next) => next,
201	        // Used by the Ollama runner while it pulls.
202	        readManifest: (tag) => readOllamaManifest(ollamaModels, tag),
203	        recordPull(tag, digest) {
204	            const digests = pulls()[tag] ||= [];
205	            if (digests.includes(digest)) return;
206	            digests.push(digest);
207	            save();
208	        },
209	        clearPulls(tag) {
210	            const recorded = state().ollamaPulls;
211	            if (!recorded?.[tag]) return;
212	            delete recorded[tag];
213	            save();
214	        },
215	    });
216	
217	    const snapshotFile = (source, file) => ({
218	        repo: source.repo, commit: source.commit, file: file.path, size: file.size,
219	        ...(file.sha256 !== undefined ? { sha256: file.sha256 } : { gitOid: file.gitOid }),
220	    });
221	
222	    async function treeBytes(dir) {
223	        let total = 0;
224	        let entries = [];
225	        try { entries = await fs.promises.readdir(dir, { withFileTypes: true }); } catch { return 0; }
226	        for (const entry of entries) {
227	            const full = path.join(dir, entry.name);
228	            if (entry.isDirectory()) total += await treeBytes(full);
229	            else if (entry.isFile()) total += (await fs.promises.lstat(full)).size;
230	        }
231	        return total;
232	    }
233	
234	    const hfSnapshot = Object.freeze({
235	        type: 'hf-snapshot',
236	        fetchedBy: 'controller',
237	        key: (source) => `hf:${source.repo}@${source.commit}`,
238	        isPinned: (source) => Boolean(source.commit && source.files?.length),
239	        // Complete only when every file has verified; a partial snapshot is never ready.
240	        async state(source) {
241	            if (!source.commit || !source.files) return { state: 'unpinned', bytes: 0, total: null };
242	            let bytes = 0;
243	            let complete = true;
244	            let partial = false;
245	            for (const file of source.files) {
246	                const inspected = await inspectSnapshot({ root: hfRoot, artifact: snapshotFile(source, file) });
247	                bytes += inspected.bytes;
248	                if (inspected.state !== 'complete') complete = false;
249	                if (inspected.state !== 'absent') partial = true;
250	            }
251	            return { state: complete ? 'complete' : (partial ? 'partial' : 'absent'), bytes, total: source.size };
252	        },
253	        async fetch({ artifact: source, signal, onProgress = () => {} }) {
254	            let done = 0;
255	            let transferred = 0;
256	            for (const file of source.files) {
257	                const result = await downloadSnapshot({
258	                    root: hfRoot,
259	                    artifact: snapshotFile(source, file),
260	                    token: env.HF_TOKEN || '',
261	                    baseUrl: hfBaseUrl,
262	                    signal,
263	                    onProgress: (progress) => onProgress({
264	                        ...progress,
265	                        bytes: done + progress.bytes,
266	                        total: source.size,
267	                        transferred: transferred + (progress.transferred ?? 0),
268	                    }),
269	                });
270	                done += file.size;
271	                transferred += result.bytesTransferred;
272	                onProgress({ bytes: done, total: source.size, transferred, rate: 0, etaSeconds: null });
273	            }
274	            const { dir } = snapshotPaths({ root: hfRoot, repo: source.repo, commit: source.commit });
275	            return { path: dir, bytes: source.size, bytesTransferred: transferred };
276	        },
277	        // Delete weights removes the whole snapshot and its bookkeeping.
278	        async remove(source) {
279	            if (!source.commit) return 0;
280	            const { dir, stateDir } = snapshotPaths({ root: hfRoot, repo: source.repo, commit: source.commit });
281	            const freed = await treeBytes(dir) + await treeBytes(stateDir);
282	            await fs.promises.rm(dir, { recursive: true, force: true });
283	            await fs.promises.rm(stateDir, { recursive: true, force: true });
284	            return freed;
285	        },
286	        // Pinning reads Hugging Face metadata only; no weights are downloaded.
287	        async pin(source) {
288	            if (source.commit && source.files) return source;
289	            const resolved = await resolveSnapshot({
290	                repo: source.repo,
291	                revision: source.revision || 'main',
292	                token: env.HF_TOKEN || '',
293	                baseUrl: hfBaseUrl,
294	            });
295	            const files = resolved.files.map((file) => ({ ...file }));
296	            return { ...source, commit: resolved.commit, files, size: files.reduce((sum, file) => sum + file.size, 0) };
297	        },
298	        // An update keeps the pin while repository and revision are unchanged.
299	        carryPin(next, previous) {
300	            if (next.commit || previous?.type !== 'hf-snapshot' || !previous.commit) return next;
301	            if (next.repo !== previous.repo || next.revision !== previous.revision) return next;
302	            return { ...next, commit: previous.commit, files: previous.files, size: previous.size };
303	        },
304	    });
305	
306	    return Object.freeze({ huggingface, ollama, 'hf-snapshot': hfSnapshot });
307	}
